powerpagecomponent.content:
{
  "source": "<div id="cmdspp-page-loader" class="cmdspp-loader-overlay">
  <div class="cmdspp-loader-content">
    <div class="spinner-border text-primary" role="status" style="width: 3rem; height: 3rem;">
      <span class="visually-hidden">Loading...</span>
    </div>
    <div class="mt-3 fw-bold text-secondary">Loading Application Form...</div>
  </div>
</div>
<div id="wizardContainer"></div>

<style>
  .cmdspp-form-body {
    padding: 24px;
    padding-top: 10px !important;
    width: 100%;
    gap: 16px
  }

  .accordion-container {
    width: 100%
  }

  .cmdspp-loader-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-color: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(4px);
    z-index: 99999;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: opacity 0.3s ease, visibility 0.3s ease;
  }

  .cmdspp-loader-content {
    text-align: center;
  }

  .cmdspp-loader-overlay.hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
  }
</style>



<script>
  (function () {
    "use strict";

    // Global Caches
    window.cmdsppOptionMaps = window.cmdsppOptionMaps || {};
    window.cmdsppLookupCache = window.cmdsppLookupCache || {};
    window.loadedSections = window.loadedSections || new Set();
    let cachedToken = null;

    // Memoized token fetch - prevents network delays on token check
    async function getAntiForgeryToken() {
      if (cachedToken) return cachedToken;
      return new Promise((resolve) => {
        if (window.shell && typeof window.shell.getTokenDeferred === "function") {
          window.shell.getTokenDeferred().done((token) => { cachedToken = token; resolve(token); })
            .fail(() => { cachedToken = fallbackToken(); resolve(cachedToken); });
          return;
        }
        if (typeof window.getAuthenticationToken === "function") {
          try {
            const token = window.getAuthenticationToken();
            if (token) { cachedToken = token; return resolve(token); }
          } catch (e) { }
        }
        cachedToken = fallbackToken();
        resolve(cachedToken);
      });
    }

    function fallbackToken() {
      const inputToken = document.querySelector('input[name="__RequestVerificationToken"]')?.value;
      return inputToken || window.__RequestVerificationToken || "";
    }

    async function safeWebApiClient(options) {
      const token = await getAntiForgeryToken();
      if (window.webapi && typeof window.webapi.safeAjax === "function") {
        return window.webapi.safeAjax(options);
      }
      return $.ajax({
        ...options,
        headers: {
          "__RequestVerificationToken": token,
          "Accept": "application/json",
          "Content-Type": "application/json; charset=utf-8",
          ...(options.headers || {})
        }
      });
    }

    try {
      const schemaEl = document.getElementById("wizardSchemaData");

      window.wizardSchema = schemaEl
        ? JSON.parse(schemaEl.textContent || "[]")
        : [];

      /*
       * Sort dynamically by headerPrefix.
       * No hard-coded prefix list required.
       */
      window.wizardSchema.sort(function (a, b) {

        const prefixA = String(
          a.headerPrefix || ""
        ).trim();

        const prefixB = String(
          b.headerPrefix || ""
        ).trim();

        return prefixA.localeCompare(
          prefixB,
          undefined,
          {
            numeric: true,
            sensitivity: "base"
          }
        );

      });

      console.log(
        "SORTED wizardSchema:",
        window.wizardSchema
      );
      //console.log("window.wizardSchema",window.wizardSchema);
    } catch (err) {
      alert("System Error - Pls contact technical support !")
      window.wizardSchema = [];
    }

    if (!window.wizardSchema.length) return;

    function getEntitySet(logicalName) {
      if (!logicalName) return "";
      if (logicalName.endsWith("s")) return logicalName;
      if (logicalName.endsWith("y")) return logicalName.slice(0, -1) + "ies";
      return logicalName + "s";
    }

    function toISODateString(val) {
      if (!val) return "";
      if (typeof val === "string" && val.includes("T")) return val.split("T")[0];
      const d = new Date(val);
      return isNaN(d) ? val : d.toISOString().split("T")[0];
    }

    function getLabelFromLookupCache(value) {
      if (value === undefined || value === null || value === "") return "";
      if (window.cmdsppOptionMaps && window.cmdsppOptionMaps[value]) {
        return window.cmdsppOptionMaps[value];
      }

      for (const key in window.cmdsppLookupCache) {
        const optionsList = window.cmdsppLookupCache[key];
        if (Array.isArray(optionsList)) {
          const match = optionsList.find(opt => opt && opt.value !== null && String(opt.value) === String(value));
          if (match) {
            return match.label;
          }
        }
      }
      return value;
    }

    class CommonTableTemplate {
      constructor(tableId, options = {}) {
        this.tableId = tableId;
        this.options = options;
        this.pageSize = options.pageSize || 4;
        this.currentPage = 1;
        this._allRecords = [];
        this._columns = [];
      }

      static formatDate(value) {
        if (!value) return "";
        const cleanVal = toISODateString(value);
        const parts = cleanVal.split("-");
        return parts.length === 3 ? `${parts[1]}/${parts[2]}/${parts[0]}` : value;
      }

      getDisplayValue(column, record, fields) {
        const val = record[column.field];
        if (val === undefined || val === null || val === "") return "";
        if (record[column.field + "_label"]) return record[column.field + "_label"];
        return getLabelFromLookupCache(val);
      }

      render(columns, records, fields) {
        this._columns = columns || this._columns;
        this._allRecords = records || this._allRecords;
        this.fields = fields || this.fields;
        this._renderCurrentPage();
      }

      goToPage(page) {
        this.currentPage = page;
        this._renderCurrentPage();
      }

      _renderCurrentPage() {
        const activeRecords = (this._allRecords || []).filter(r => !r.isDeleted);
        const totalCount = activeRecords.length;
        const pageSize = this.pageSize > 0 ? this.pageSize : totalCount || 1;
        const totalPages = Math.ceil(totalCount / pageSize) || 1;

        if (this.currentPage > totalPages) this.currentPage = totalPages;

        const start = (this.currentPage - 1) * pageSize;
        const pageRecords = activeRecords.slice(start, start + pageSize);

        this._draw(this._columns, pageRecords, {
          visibleCount: pageRecords.length,
          totalCount: totalCount,
          currentPage: this.currentPage,
          hasPrev: this.currentPage > 1,
          hasNext: start + pageSize < totalCount,
          onPrev: () => this.goToPage(this.currentPage - 1),
          onNext: () => this.goToPage(this.currentPage + 1)
        });
      }

      _draw(columns, records, pagination) {
        const root = document.getElementById(this.tableId);
        if (!root) return;

        const header = root.querySelector("#cmdspp-table-header");
        const body = root.querySelector("#cmdspp-table-body");

        if (header) header.innerHTML = `<tr>${columns.map(col => `<th>${col.label}</th>`).join("")}</tr>`;

        if (body) {
          if (!records || records.length === 0) {
            body.innerHTML = `<tr><td colspan="${columns.length}" class="cmdspp-no-data">No Records Found</td></tr>`;
          } else {
            body.innerHTML = records.map((record) => {
              const recordKey = record.recordId || record.dbId;
              return `
              <tr data-record-id="${recordKey}">
                ${columns.map(column => {
                if (column.field === "actions" || column.type === "actions") {
                  return `
                      <td>
                        <div class="cmdspp-action-group">
                          <button type="button" class="cmdspp-action-icon cmdspp-edit-btn" data-action="edit" data-record-id="${recordKey}" title="Edit">
                            <img src="/tableediticon.svg" alt="Edit" style="pointer-events:none;">
                          </button>
                          <button type="button" class="cmdspp-action-icon cmdspp-delete-btn" data-action="delete" data-record-id="${recordKey}" title="Delete">
                            <img src="/tablecancelicon.svg" alt="Delete" style="pointer-events:none;">
                          </button>
                        </div>
                      </td>`;
                }
                if (column.type === "date") {
                  return `<td>${CommonTableTemplate.formatDate(record[column.field])}</td>`;
                }
                return `<td>${this.getDisplayValue(column, record, this.fields)}</td>`;
              }).join("")}
              </tr>`;
            }).join("");

            body.onclick = (e) => {
              const btn = e.target.closest(".cmdspp-action-icon");
              if (!btn) return;
              e.preventDefault();
              e.stopPropagation();

              const action = btn.getAttribute("data-action");
              const recId = btn.getAttribute("data-record-id");
              const record = this._allRecords.find(r => String(r.recordId || r.dbId) === String(recId));

              if (!record) return;

              if (action === "edit" && this.options.actions?.onEdit) {
                this.options.actions.onEdit(record);
              } else if (action === "delete" && this.options.actions?.onDelete) {
                this.options.actions.onDelete(record);
              }
            };
          }
        }
        this.renderPagination(pagination, records.length, root);
      }

      renderPagination(pagination, totalRecords, root) {
        const infoLabel = root.querySelector("#cmdspp-pagination-info");
        const pageNumbersContainer = root.querySelector("#cmdspp-page-numbers");
        const prevBtn = root.querySelector("#cmdspp-prev-page");
        const nextBtn = root.querySelector("#cmdspp-next-page");

        if (!pagination) return;
        if (infoLabel) infoLabel.innerText = `Showing ${pagination.visibleCount} of ${pagination.totalCount} records`;
        if (pageNumbersContainer) pageNumbersContainer.innerHTML = `<button type="button" class="cmdspp-page-number active" data-page="${pagination.currentPage}" disabled>${pagination.currentPage}</button>`;

        if (prevBtn) {
          prevBtn.disabled = !pagination.hasPrev;
          prevBtn.onclick = () => pagination.hasPrev && pagination.onPrev();
        }
        if (nextBtn) {
          nextBtn.disabled = !pagination.hasNext;
          nextBtn.onclick = () => pagination.hasNext && pagination.onNext();
        }
      }
    }

    class cmdsppFormRenderer {
      constructor(formData) {
        this.formData = formData;
        this.containerId = formData.containerId;
        this.formDefinition = formData.fields || [];
        this.formValues = {};
        this.errors = {};
        this.initValues();
      }

      initValues() {
        this.formDefinition.forEach(field => {
          const initial = field.value;
          if (field.type === "checkbox") this.formValues[field.name] = !!initial;
          else if (field.type === "checkboxgroup" || field.type === "multiselect") this.formValues[field.name] = Array.isArray(initial) ? initial : [];
          else if (field.type === "date" && initial) this.formValues[field.name] = toISODateString(initial);
          else if (initial !== undefined && initial !== null && initial !== "") this.formValues[field.name] = initial;

          if (field.options) {
            field.options.forEach(opt => window.cmdsppOptionMaps[opt.value] = opt.label);
          }
        });
      }

      setWithExpiry(key, value, ttlInMinutes = 60) {
        const item = {
          value: value,
          expiry: Date.now() + ttlInMinutes * 60 * 1000,
        };
        localStorage.setItem(key, JSON.stringify(item));
      }

      getWithExpiry(key) {
        const itemStr = localStorage.getItem(key);
        if (!itemStr) return null;

        const item = JSON.parse(itemStr);
        if (Date.now() > item.expiry) {
          localStorage.removeItem(key);
          return null; // Expired
        }
        return item.value;
      }

      async loadLookups() {
        const lookupFields = this.formDefinition.filter(
          f => (f.type === "lookup" || f.type === "checkboxgroup" || f.type === "multiselect" || f.type === "select") && f?.source?.table
        );

        if (!lookupFields.length) return;

        const promises = lookupFields.map(async field => {
          const cacheKey = `${field.source.table}_${field.source.domainName}_${field.source.domainVal}`;

          if (window.cmdsppLookupCache[cacheKey]) {
            field.options = window.cmdsppLookupCache[cacheKey];
            return;
          }
          else {
            const cachedData = this.getWithExpiry(cacheKey);
            if (cachedData) {
              window.cmdsppLookupCache[cacheKey] = cachedData;
              field.options = cachedData;
              return;
            }
          }

          const url = `/_api/${field.source.table}?$filter=${field.source.domainName} eq '${field.source.domainVal}'&$select=${field.source.valueField},${field.source.labelField}`;

          try {
            const response = await safeWebApiClient({ type: "GET", url: url });
            const options = (response.value || []).map(item => {
              const val = item[field.source.valueField];
              const lbl = item[field.source.labelField];
              window.cmdsppOptionMaps[val] = lbl;
              return { label: lbl, value: val };
            });

            window.cmdsppLookupCache[cacheKey] = options;
            this.setWithExpiry(cacheKey, options, 30);
            field.options = options;
          } catch (err) {
            console.error("Error loading options:", err);
          }
        });

        await Promise.all(promises);
      }

      isVisible(field) {
            if (!field.dependency || !field.dependency.length) return true;

            // Hide-on-match deps (type: visibility + fieldHide: true) — OR logic
            const hideDeps = field.dependency.filter(d => d.type === "visibility" && d.fieldHide);
            if (hideDeps.length) {
              const shouldHide = hideDeps.some(dep =>
                dep.depId.some(parentField => {
                  const parentLabel = getLabelFromLookupCache(this.formValues[parentField]);
                  return String(parentLabel) === String(dep.value);
                })
              );
              if (shouldHide) return false;
            }

            // Show-on-match deps (type: visibility, no fieldHide) — AND logic, same as before
            const showDeps = field.dependency.filter(d => d.type === "visibility" && !d.fieldHide);
            if (showDeps.length) {
              return showDeps.every(dep =>
                dep.depId.every(parentField => {
                  const parentValue = this.formValues[parentField];
                  if (parentValue === undefined || parentValue === null || parentValue === "") return false;
                  if (typeof parentValue === "boolean") {
                    return parentValue === (dep.value === "Yes" || String(dep.value).toLowerCase() === "yes" || dep.value === true);
                  }
                  return Array.isArray(parentValue) ? parentValue.includes(dep.value) : String(parentValue) === String(dep.value);
                })
              );
            }

            return true;
          }

      renderFieldHtml(field) {
        let value = this.formValues[field.name] ?? "";
        if (field.type === "date" && value) value = toISODateString(value);

        const required = field.validations?.some(v => v.type === "mandatory") ? '<span class="text-danger">*</span>' : '';
        const invalid = this.errors[field.name] ? "is-invalid" : "";
        const errorMsg = this.errors[field.name] ? `<div class="text-danger small mt-1">${this.errors[field.name]}</div>` : "";

        switch (field.type) {
          // case "input":
          //   return `<label class="form-label">${field.label} ${required}</label>
          //           <input type="text" class="form-control ${invalid}" data-field="${field.name}" value="${value}" maxLength="${field.maxLength}" placeholder="${field.placeholder || ''}" />${errorMsg}`;
          case "input":
            let extraHtml = "";
            let autoCompleteAttr = "";

            if (field.addrFill) {
              extraHtml = `<ul id="cmdspp_melissa_suggestions_${this.containerId}_${field.name}" class="list-group shadow-sm" style="position: absolute; z-index: 1050; width: 95%; display: none; max-height: 200px; overflow-y: auto; margin-top: 2px;"></ul>`;
              autoCompleteAttr = `autocomplete="off"`;

              return `<div style="position: relative;">
                          <label class="form-label">${field.label} ${required}</label>
                          <input type="text" class="form-control ${invalid}" data-field="${field.name}" value="${value}" maxLength="${field.maxLength || ''}" placeholder="${field.placeholder || ''}" ${autoCompleteAttr} />
                          ${extraHtml}${errorMsg}
                        </div>`;
            }

            // Default input rendering
            return `<label class="form-label">${field.label} ${required}</label>
                  <input type="text" ${field.readOnly ? "disabled" : ""} class="form-control ${invalid}" data-field="${field.name}" value="${value}" maxLength="${field.maxLength || ''}" placeholder="${field.placeholder || ''}" />${errorMsg}`;
          case "number":
            return `<label class="form-label">${field.label} ${required}</label>
                  <input type="number" class="form-control ${invalid}" data-field="${field.name}" value="${value}" placeholder="${field.placeholder || ''}" />${errorMsg}`;
          case "date":
            return `<label class="form-label">${field.label} ${required}</label>
                  <input type="date" class="form-control ${invalid}" data-field="${field.name}" value="${value}" />${errorMsg}`;
          case "checkbox":
  return `
    <div class="form-check">
      <input 
        type="checkbox"
        class="form-check-input ${invalid}"
        data-field="${field.name}"
        id="${field.name}"
        ${value ? "checked" : ""}
        ${field.readOnly ? "disabled" : ""}
      />
      <label class="form-check-label" for="${field.name}">
        ${field.label} ${required}
      </label>
    </div>
    ${errorMsg}`;
          case "checkboxgroup":
          case "multiselect": {
            const selected = Array.isArray(value) ? value.map(String) : [];
            return `<label class="form-label">${field.label} ${field.label ? required :""}</label>
                  <div class="cmdspp-checkbox-group" data-checkbox-group="${field.name}">
                    ${(field.options || []).map(o => `
                      <div class="form-check">
                        <input type="checkbox" class="form-check-input" 
                              name="${field.name}" 
                              value="${o.value}" 
                              data-field-group="${field.name}"
                              id="${field.name}_${o.value}"
                              ${selected.includes(String(o.value)) ? "checked" : ""}>
                        <label class="form-check-label" for="${field.name}_${o.value}">${o.label}</label>
                      </div>
                    `).join("")}
                  </div>${errorMsg}`;
          }
          case "lookup":
          case "select":
            return `<label class="form-label">${field.label} ${required}</label>
                  <select class="form-select ${invalid}" data-field="${field.name}" id="${field.name}">
                    <option value="">Select</option>
                    ${(field.options || []).map(o => `<option value="${o.value}" ${String(value) === String(o.value) ? "selected" : ""}>${o.label}</option>`).join("")}
                  </select>${errorMsg}`;
          case "radio":
            return `
                  <div class="cmdspp-radio-row">
                 <label class="form-label cmdspp-radio-row-label">${field.label} ${required}</label>
                  <div class="cmdspp-segmented">
                    ${(field.options || []).map(o => `
                      <label class="cmdspp-segment-item">
                        <input type="radio" name="${field.name}_${this.containerId}" value="${o.value}" data-field="${field.name}" ${String(value) === String(o.value) ? "checked" : ""}>
                        <span class="cmdspp-segment-text">${o.label}</span>
                      </label>
                    `).join("")}
                  </div>
                  </div>${errorMsg}`;
          default: return "";
        }
      }

      renderForm() {
        const host = document.getElementById(this.containerId);
        if (!host) return;

        let html = `<div class="cmdspp-form-card">`;

        // Render note from JSON before fields
        if (this.formData.note && this.formData.note.text) {

          const noteType = this.formData.note.type || "info";

          html += `
            <div class="cmdspp-form-note form-label mb-3">
                ${this.formData.note.text}
            </div>
        `;
        }

        html += `<div class="row">`;

        this.formDefinition.forEach(field => {

          const displayStyle = this.isVisible(field)
            ? "block"
            : "none";

          html += `
            <div
                class="col-md-${field.column || 6} mb-3"
                data-field-container="${field.name}"
                style="display: ${displayStyle};">

                ${this.renderFieldHtml(field)}

            </div>
        `;
        });

        html += `</div>`;

        const isEditing = !!this.formValues.__editingId;

        const isSubGridSection =
          !!this.formData.tableId &&
          Array.isArray(this.formData.fieldMappings);

        if (
          this.formData.showSubmitButton !== false &&
          isSubGridSection
        ) {

          html += `
            <div class="cmdspp-action-bar mt-3 d-flex gap-2">

                <button
                    type="button"
                    id="${this.formData.addBtnId}"
                    class="btn btn-primary cmdspp-submit-btn">

                    ${isEditing
              ? (this.formData.editBtnLabel || "Update")
              : this.formData.primaryBtnLabel
            }

                </button>

                ${isEditing
              ? `
                            <button
                                type="button"
                                class="btn btn-outline-secondary cmdspp-cancel-btn">
                                Cancel Edit
                            </button>
                          `
              : ""
            }

            </div>
        `;
        }

        html += `</div>`;

        host.innerHTML = html;

        this.bindEvents();
      }

      isEmptyValue(value) {

        if (Array.isArray(value)) {
          return value.length === 0;
        }

        return value === undefined || value === null || String(value).trim() === "";
      }

      validateField(field) {

        if (!this.isVisible(field))
          return null;

        const value = this.formValues[field.name];

        if (!field.validations)
          return null;

        for (let validation of field.validations) {

          switch (validation.type) {

            case "mandatory":

              if (this.isEmptyValue(value)) {
                return validation.message ||
                  `${field.label} is required`;
              }
              if(field.type==="checkbox" && !value){
                 return validation.message || `${field.label} is required`;
              }

              break;


            case "email":

              if (value) {

                const regex =
                  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

                if (!regex.test(String(value)))
                  return validation.message;
              }

              break;


            case "pattern":

              if (value !== undefined &&
                value !== null &&
                String(value).length > 0) {

                try {

                  const regex =
                    new RegExp(validation.regex);

                  if (!regex.test(String(value))) {

                    return validation.message ||
                      `Invalid ${field.label}.`;

                  }

                } catch (error) {

                  console.error(
                    `Invalid regex for ${field.name}:`,
                    validation.regex,
                    error
                  );

                }

              }

              break;


            case "numeric":

              if (
                value &&
                isNaN(value)
              ) {
                return validation.message;
              }

              break;


            case "minLength":

              if (
                value &&
                value.length < validation.value
              ) {
                return validation.message;
              }

              break;


            case "maxLength":

              if (
                value &&
                value.length > validation.value
              ) {
                return validation.message;
              }

              break;


            case "minValue":

              if (
                value &&
                Number(value) < validation.value
              ) {
                return validation.message;
              }

              break;


            case "maxValue":

              if (
                value &&
                Number(value) > validation.value
              ) {
                return validation.message;
              }

              break;


            case "pastDate":

              if (
                value &&
                new Date(value) > new Date()
              ) {
                return validation.message;
              }

              break;

           case "notEqualField":

              if (value && this.formValues[validation.field]) {
                const currentLabel = getLabelFromLookupCache(value);
                const otherLabel = getLabelFromLookupCache(this.formValues[validation.field]);

                if (String(currentLabel) === String(otherLabel)) {
                  return validation.message || `${field.label} cannot be the same as the related field.`;
                }
              }

              break;
            
            case "futureDate":

              if (
                value &&
                new Date(value) < new Date()
              ) {
                return validation.message;
              }

              break;

              case "dateFormat":

  if (value) {
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

    if (!dateRegex.test(String(value))) {
      return validation.message;
    }

    const date = new Date(value);

    if (isNaN(date.getTime())) {
      return validation.message;
    }
  }

  break;


case "dateComparison":

  if (value && validation.compareWith) {

    const compareValue = this.formValues[validation.compareWith];

    if (compareValue) {

      const currentDate = new Date(value);
      const compareDate = new Date(compareValue);

      if (validation.operator === "lessThanOrEqual" &&
          currentDate > compareDate) {
        return validation.message;
      }

      if (validation.operator === "greaterThanOrEqual" &&
          currentDate < compareDate) {
        return validation.message;
      }
    }
  }

  break;

          }
        }

        return null;
      }
      validateForm() {

        this.errors = {};

        this.formDefinition.forEach(field => {

          if (!this.isVisible(field))
            return;

          const error =
            this.validateField(field);

          if (error) {
            this.errors[field.name] = error;
          }

        });

        return Object.keys(this.errors).length === 0;
      }


      bindEvents() {
        const root = document.getElementById(this.containerId);

        root.querySelectorAll("[data-field]").forEach(control => {
          const syncValue = (e) => {
            const fieldName = e.target.dataset.field;
            const val = e.target.type === "checkbox" ? e.target.checked : e.target.value;
            this.formValues[fieldName] = val;
          };

          control.addEventListener("input", syncValue);
          control.addEventListener("change", (e) => {
            syncValue(e);
            this.updateVisibility();
          });
        });
        root.querySelectorAll("[data-field-group]").forEach(control => {
          control.addEventListener("change", (e) => {
            const fieldName = e.target.dataset.fieldGroup;
            const groupEl = root.querySelector(`[data-checkbox-group="${fieldName}"]`);
            const checked = Array.from(groupEl.querySelectorAll("input:checked")).map(cb => cb.value);
            this.formValues[fieldName] = checked;
            this.updateVisibility();
          });
        });

        const submitBtn = root.querySelector(".cmdspp-submit-btn");
        if (submitBtn) {
          submitBtn.onclick = (e) => {
            e.preventDefault();
            if (!this.validateForm()) {
              this.renderForm(); // redraw with errors
              return;
            }
            this.submitForm();
          };
        }

        const cancelBtn = root.querySelector(".cmdspp-cancel-btn");
        if (cancelBtn) {
          cancelBtn.onclick = (e) => {
            e.preventDefault();
            this.reset();
          };
        }

       //Melissa
        const addrFields = this.formDefinition.filter(f => f.addrFill);

        addrFields.forEach(addrField => {
          const addressInput = root.querySelector(`input[data-field="${addrField.name}"]`);

          if (addressInput) {
            let debounceTimer;
            addressInput.addEventListener("input", (e) => {
              const searchText = e.target.value;
              const suggestionBox = root.querySelector(`#cmdspp_melissa_suggestions_${this.containerId}_${addrField.name}`);

              clearTimeout(debounceTimer);
              if (searchText.length < 4) {
                suggestionBox.style.display = 'none';
                return;
              }

              debounceTimer = setTimeout(async () => {
                try {
                  const response = await safeWebApiClient({
                    type: "POST",
                    url: "/_api/serverlogics/melissaAutopopulate",
                    data: JSON.stringify({ searchText: searchText })
                  });

                  //const result = typeof response === "string" ? JSON.parse(response?.data) : response?.data;
                  const result = JSON.parse(response?.data);
                  if (result.status === "success" && result.results.length > 0) {
                    suggestionBox.innerHTML = '';
                    result.results.forEach(item => {
                      const li = document.createElement("li");
                      li.className = "list-group-item list-group-item-action";
                      li.style.cursor = "pointer";
                      li.textContent = `${item.Address.Address1}, ${item.Address.Locality}, ${item.Address.AdministrativeArea} ${item.Address.PostalCode}`;

                      li.onclick = () => {
                        // 1. Update text input fields directly
                        this.formValues[addrField.name] = item.Address.Address1;
                        
                        const zipDef = this.formDefinition.find(f => f.name.toLowerCase().includes("zip"));
                        if (zipDef) this.formValues[zipDef.name] = item.Address.PostalCode;

                        // 2. Safely find Dropdowns using the exact Dataverse Source Domain!
                        const cityDef = this.formDefinition.find(f => f.source?.domainVal === "G_TOWN_CD" || f.label.toLowerCase().includes("city"));
                        const stateDef = this.formDefinition.find(f => f.source?.domainVal === "G_US_STATE_CD" || f.label.toLowerCase().includes("state"));
                        const countyDef = this.formDefinition.find(f => f.source?.domainVal === "G_CNTY_CD" || f.label.toLowerCase().includes("county"));

                        const stateMap = {
                            "AL": "Alabama", "AK": "Alaska", "AZ": "Arizona", "AR": "Arkansas", "CA": "California",
                            "CO": "Colorado", "CT": "Connecticut", "DE": "Delaware", "FL": "Florida", "GA": "Georgia",
                            "HI": "Hawaii", "ID": "Idaho", "IL": "Illinois", "IN": "Indiana", "IA": "Iowa",
                            "KS": "Kansas", "KY": "Kentucky", "LA": "Louisiana", "ME": "Maine", "MD": "Maryland",
                            "MA": "Massachusetts", "MI": "Michigan", "MN": "Minnesota", "MS": "Mississippi", "MO": "Missouri",
                            "MT": "Montana", "NE": "Nebraska", "NV": "Nevada", "NH": "New Hampshire", "NJ": "New Jersey",
                            "NM": "New Mexico", "NY": "New York", "NC": "North Carolina", "ND": "North Dakota", "OH": "Ohio",
                            "OK": "Oklahoma", "OR": "Oregon", "PA": "Pennsylvania", "RI": "Rhode Island", "SC": "South Carolina",
                            "SD": "South Dakota", "TN": "Tennessee", "TX": "Texas", "UT": "Utah", "VT": "Vermont",
                            "VA": "Virginia", "WA": "Washington", "WV": "West Virginia", "WI": "Wisconsin", "WY": "Wyoming"
                        };

                        const matchDropdownOption = (fieldDef, searchTexts) => {
                            if (!fieldDef || !fieldDef.options) return null;
                            
                            let searchArray = Array.isArray(searchTexts) ? searchTexts : [searchTexts];
                            searchArray = searchArray.filter(t => t).map(t => String(t).trim().toLowerCase());
                            
                            for (let searchLower of searchArray) {
                                const matched = fieldDef.options.find(opt => 
                                    String(opt.label).trim().toLowerCase() === searchLower ||
                                    String(opt.value).trim().toLowerCase() === searchLower
                                );
                                if (matched) return matched.value;
                            }
                            return null;
                        };

                        // 3. Map City
                        if (cityDef) {
                            const cityVal = matchDropdownOption(cityDef, item.Address.Locality);
                            if (cityVal) this.formValues[cityDef.name] = cityVal;
                        }

                        // 4. Map County
                        if (countyDef) {
                            const melissaCounty = item.Address.SubAdministrativeArea || "";
                            const countyVariations = [
                                melissaCounty, 
                                melissaCounty.replace(/ county$/i, "").trim(), 
                                `${melissaCounty} County`
                            ];
                            const countyVal = matchDropdownOption(countyDef, countyVariations);
                            if (countyVal) this.formValues[countyDef.name] = countyVal;
                        }

                        // 5. Map State 
                        if (stateDef) {
                            const melissaState = item.Address.AdministrativeArea;
                            const fullStateName = stateMap[melissaState] || melissaState;
                            const stateVal = matchDropdownOption(stateDef, [melissaState, fullStateName]);
                            if (stateVal) this.formValues[stateDef.name] = stateVal;
                        }

                        // 6. Hide box & re-render the form
                        suggestionBox.style.display = 'none';
                        this.renderForm();
                        
                        const newTarget = document.querySelector(`#${this.containerId} input[data-field="${addrField.name}"]`);
                        if (newTarget) newTarget.blur();
                      };
                      suggestionBox.appendChild(li);
                    });
                    suggestionBox.style.display = 'block';
                  }
                } catch (err) {
                  console.error("Melissa Autopopulate Error:", err);
                }
              }, 400);
            });

            document.addEventListener('click', (e) => {
              const suggestionBox = root.querySelector(`#cmdspp_melissa_suggestions_${this.containerId}_${addrField.name}`);
              if (suggestionBox && e.target !== addressInput && !suggestionBox.contains(e.target)) {
                suggestionBox.style.display = 'none';
              }
            });
          }
        });

      }

      updateVisibility() {
        this.formDefinition.forEach(field => {
          const el = document.querySelector(`#${this.containerId} [data-field-container="${field.name}"]`);
          const visible = this.isVisible(field);
          if (el) el.style.display = visible ? "block" : "none";

          if (!visible) {
            const hideDeps = (field.dependency || []).filter(d => d.type === "visibility" && d.fieldHide);
            const matchedDep = hideDeps.find(dep =>
              dep.depId.some(parentField => {
                const parentLabel = getLabelFromLookupCache(this.formValues[parentField]);
                return String(parentLabel) === String(dep.value);
              })
            );

            if (matchedDep && matchedDep.autopopulate !== undefined) {
              const match = (field.options || []).find(o => String(o.label) === String(matchedDep.autopopulate));
              this.formValues[field.name] = match ? match.value : matchedDep.autopopulate;
            } else {
              delete this.formValues[field.name];
            }
          }
        });
        }

      submitForm() {
        const isEditing = !!this.formValues.__editingId;
        const editingId = this.formValues.__editingId;
        const valuesToSend = { ...this.formValues };
        delete valuesToSend.__editingId;

        this.formDefinition.forEach(field => {
          if (valuesToSend[field.name] !== undefined) {
            const val = valuesToSend[field.name];
            if (field.type === "date" && val) valuesToSend[field.name] = toISODateString(val);

            const label = getLabelFromLookupCache(val);
            if (label) valuesToSend[field.name + "_label"] = label;
          }
        });

        // NEW: duplicate check — only runs if section.duplicateCheckFields is defined in schema
        const section = window.wizardSchema.find(s => s.containerId === this.containerId);
        const isSubGridSection = section && !!section.tableId && Array.isArray(section.fieldMappings);
        const duplicateFields = (Array.isArray(section?.duplicateCheckFields) && section.duplicateCheckFields.length > 0)
        ? section.duplicateCheckFields
        : this.formDefinition.map(f => f.name);

        if (isSubGridSection && !isEditing && Array.isArray(duplicateFields) && duplicateFields.length > 0) {
          const isDuplicate = (section.records || [])
            .filter(r => !r.isDeleted)
            .some(existing =>
              duplicateFields.every(fieldName => {
                const newVal = valuesToSend[fieldName];
                const existingVal = existing[fieldName];
                if (Array.isArray(newVal) || Array.isArray(existingVal)) {
                  const a = Array.isArray(newVal) ? [...newVal].map(String).sort() : [];
                  const b = Array.isArray(existingVal) ? [...existingVal].map(String).sort() : [];
                  return JSON.stringify(a) === JSON.stringify(b);
                }
                return String(newVal ?? "") === String(existingVal ?? "");
              })
            );

          if (isDuplicate) {
            alert("This record already exists in the table.");
            
            return; // stop here — do not dispatch, do not reset
          }
        }

        window.dispatchEvent(new CustomEvent("dynamicFormSubmit", {
          detail: {
            containerId: this.containerId,
            isEditing,
            editingId,
            values: valuesToSend,
            formFlds: this.formDefinition
          }
        }));

        this.reset();
      }

      setValues(values, editingId) {
        this.formValues = {};
        this.initValues();

        if (values && typeof values === "object") {
          Object.keys(values).forEach(key => {
            const val = values[key];
            this.formValues[key] = (val === null || val === undefined) ? "" : val;
          });
        }

        this.formDefinition.forEach(field => {
          if (field.type === "date" && this.formValues[field.name]) {
            this.formValues[field.name] = toISODateString(this.formValues[field.name]);
          }
          if (field.type === "radio" && this.formValues[field.name]) {
            this.formValues[field.name] = this.formValues[field.name] === true || this.formValues[field.name] === "Yes" ? "Yes" : "No";
          }
        });

        if (editingId !== undefined && editingId !== null) {
          this.formValues.__editingId = editingId;
        }

        this.renderForm();
        this.updateVisibility();

        const el = document.getElementById(this.containerId);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }

      resetsection() {
        this.formValues = {};
        this.initValues();
        // this.renderForm();
      }

      reset() {
        this.formValues = {};
        this.initValues();
        this.renderForm();
      }

      async renderMe() {
        await this.loadLookups();
        this.renderForm();
        return this;
      }


    }

    // ---------------------------------------------------------------------------
    // Multi-table helpers
    // ---------------------------------------------------------------------------
    // section.entitySet can contain one or more entity sets separated by commas.
    // When more than one table is configured, records keep their source table
    // and primary-key field so EDIT and DELETE always go back to the same table.
    function getSectionEntitySets(section) {
      return String(section?.entitySet || "")
        .split(",")
        .map(s => s.trim())
        .filter(Boolean);
    }

    function getSectionParentLookupFields(section) {
      return String(section?.parentLookupField || "")
        .split(",")
        .map(s => s.trim())
        .filter(Boolean);
    }

    function getSectionRecordIdFields(section) {
      return String(section?.recordIdField || section?.primaryKey || "")
        .split(",")
        .map(s => s.trim())
        .filter(Boolean);
    }

    function getEntitySetForRecord(section, record) {
      if (record?._entitySet) return record._entitySet;
      return getSectionEntitySets(section)[0] || "";
    }

    function getRecordIdFieldForEntity(section, entitySet, indexHint) {
      const entitySets = getSectionEntitySets(section);
      const idFields = getSectionRecordIdFields(section);
      const index = entitySets.indexOf(entitySet);

      if (index >= 0 && idFields[index]) return idFields[index];
      if (indexHint !== undefined && idFields[indexHint]) return idFields[indexHint];
      return idFields[0] || "";
    }

    function getParentLookupFieldForEntity(section, entitySet, indexHint) {
      const entitySets = getSectionEntitySets(section);
      const lookupFields = getSectionParentLookupFields(section);
      const index = entitySets.indexOf(entitySet);

      if (index >= 0 && lookupFields[index]) return lookupFields[index];
      if (indexHint !== undefined && lookupFields[indexHint]) return lookupFields[indexHint];
      return lookupFields[0] || "";
    }

    function getRecordIdFromEntityRecord(item, section, entitySet, indexHint) {
      const idField = getRecordIdFieldForEntity(section, entitySet, indexHint);
      if (idField && item?.[idField]) return item[idField];

      // Safe fallback for Dataverse entity-set primary key naming.
      const singular = String(entitySet || "").replace(/s$/, "");
      const candidates = [
        `${entitySet}id`,
        `${singular}id`
      ];

      for (const key of candidates) {
        if (item?.[key]) return item[key];
      }

      return null;
    }

    async function fetchSectionRecords(section) {
      const parentGuid = getParentRecordGuid();
      if (!parentGuid || !section.entitySet) return [];

      const isStandalone = !section.tableId || !section.fieldMappings;
      const formInstance = window.cmdsppForms[section.containerId];
      const entitySets = getSectionEntitySets(section);
      const parentLookupFields = getSectionParentLookupFields(section);
      let rawRecords = [];

      for (let i = 0; i < entitySets.length; i++) {
        const entitySet = entitySets[i];
        const parentLookupField =
          parentLookupFields[i] || parentLookupFields[0] || section.parentLookupField;

        if (!entitySet) continue;

        const inrecordId = parentLookupField
          ? `_${parentLookupField}_value`
          : "";

        const filterQuery = isStandalone
          ? (inrecordId
              ? `${inrecordId} eq ${parentGuid} and statecode eq 0`
              : `statecode eq 0`)
          : `_cmdspp_p_sys_id_value eq ${parentGuid} and statecode eq 0`;

        try {
          const response = await safeWebApiClient({
            type: "GET",
            url: `/_api/${entitySet}?$filter=${filterQuery}`,
            headers: {
              "Prefer":
                'odata.include-annotations="OData.Community.Display.V1.FormattedValue"'
            }
          });

          rawRecords.push(
            ...(response.value || []).map(record => ({
              ...record,
              _entitySet: entitySet,
              _entityIndex: i,
              _parentLookupField: parentLookupField,
              _recordIdField: getRecordIdFieldForEntity(section, entitySet, i)
            }))
          );
        } catch (err) {
          console.error(`Failed loading records from ${entitySet}`, err);
        }
      }

      const checkboxField = section.fields?.find(
        f => f.type === "checkboxgroup" || f.type === "multiselect"
      );

      if (checkboxField && isStandalone) {
        section.records = rawRecords;
        const selectedValues = rawRecords
          .map(item => String(item[`_${checkboxField.name}_value`] ?? item[checkboxField.name]))
          .filter(v => v && v !== "undefined" && v !== "null");

        if (formInstance) {
          formInstance.formValues[checkboxField.name] = selectedValues;
          formInstance.renderForm();
        }
        return rawRecords;
      }

      if (isStandalone) {
        if (rawRecords.length > 0) {
          // For a normal standalone form, use the first matching record.
          // Keep the exact table/id metadata for safe PATCH later.
          const item = rawRecords[0];
          const populatedValues = {
            __recordId: getRecordIdFromEntityRecord(
              item,
              section,
              item._entitySet,
              item._entityIndex
            ),
            __entitySet: item._entitySet,
            __recordIdField: item._recordIdField
          };

          (section.fields || []).forEach(field => {
            const fieldName = field.name;
            const fieldType = field.type;

            if (fieldType === "lookup" || fieldType === "select") {
              const rawVal = item[`_${fieldName}_value`] ?? item[fieldName];
              const formatted = item[`_${fieldName}_value@OData.Community.Display.V1.FormattedValue`];
              populatedValues[fieldName] = rawVal;
              if (formatted) populatedValues[`${fieldName}_label`] = formatted;
            } else if (fieldType === "optionset") {
              const rawVal = item[fieldName];
              const formatted = item[`${fieldName}@OData.Community.Display.V1.FormattedValue`];
              populatedValues[fieldName] = rawVal;
              if (formatted) populatedValues[`${fieldName}_label`] = formatted;
            } else if (fieldType === "choice" || fieldType === "radio") {
              populatedValues[fieldName] =
                item[fieldName] === true ? "Yes" :
                item[fieldName] === false ? "No" : "";
            } else if (fieldType === "date") {
              populatedValues[fieldName] = toISODateString(item[fieldName]);
            } else {
              populatedValues[fieldName] = item[fieldName];
            }
          });

          if (formInstance) {
            formInstance.setValues(populatedValues);
          }
        }
        return rawRecords;
      }

      return rawRecords.map((item, index) => {
        const entitySet = item._entitySet;
        const entityIndex = item._entityIndex;
        const recId = getRecordIdFromEntityRecord(
          item,
          section,
          entitySet,
          entityIndex
        ) || `temp_${index}`;

        const mappedRecord = {
          dbId: recId,
          recordId: recId,
          isNew: false,
          _entitySet: entitySet,
          _entityIndex: entityIndex,
          _parentLookupField: item._parentLookupField,
          _recordIdField: item._recordIdField
        };

        for (const m of (section.fieldMappings || [])) {
          if (m.type === "lookup") {
            const val = item[`_${m.dataverseField}_value`] ?? item[m.dataverseField];
            mappedRecord[m.formField] = val;
            mappedRecord[`${m.formField}_label`] =
              item[`_${m.dataverseField}_value@OData.Community.Display.V1.FormattedValue`] ||
              getLabelFromLookupCache(val);
          } else if (m.type === "choice" || m.type === "optionset") {
            const rawVal = item[m.dataverseField];
            mappedRecord[m.formField] = rawVal;
            mappedRecord[`${m.formField}_label`] =
              item[`${m.dataverseField}@OData.Community.Display.V1.FormattedValue`] ||
              getLabelFromLookupCache(rawVal);
          } else if (m.type === "date") {
            mappedRecord[m.formField] = toISODateString(item[m.dataverseField]);
          } else {
            mappedRecord[m.formField] = item[m.dataverseField];
          }
        }

        return mappedRecord;
      });
    }

    // ---------------------------------------------------------------------------
    // Schema-driven source -> form mapping
    // ---------------------------------------------------------------------------
    //
    // This is intentionally additive. Existing form rendering, lookup loading,
    // Melissa address autocomplete, visibility, checkbox handling and grid
    // behavior remain unchanged.
    //
    // A Yes/No field can optionally define:
    //
    // "copyFrom": {
    //   "whenValue": "Yes",
    //   "sourceType": "serviceLocation",
    //   "source": {
    //     "entitySet": "...",
    //     "parentLookupField": "...",
    //     "filter": "statecode eq 0"
    //   },
    //   "mappings": [
    //     { "sourceField": "source_street", "targetField": "billing_street", "type": "text" },
    //     { "sourceField": "source_city", "targetField": "billing_city", "type": "lookup" }
    //   ]
    // }
    //
    // The source and target column names can be completely different.
    // ---------------------------------------------------------------------------

    function getParentRecordGuid() {
      return new URLSearchParams(window.location.search).get("record") ||
             new URLSearchParams(window.location.search).get("id");
    }

    function getSourceLookupValue(record, sourceField) {
      return record?.[`_${sourceField}_value`] ?? record?.[sourceField] ?? "";
    }

    function getSourceFormattedValue(record, sourceField) {
      return record?.[`_${sourceField}_value@OData.Community.Display.V1.FormattedValue`] ||
             record?.[`${sourceField}@OData.Community.Display.V1.FormattedValue`] ||
             "";
    }

    function getConfiguredSourceValue(record, mapping) {
      if (!record || !mapping?.sourceField) return "";

      if (mapping.type === "lookup" || mapping.type === "select") {
        return getSourceLookupValue(record, mapping.sourceField);
      }

      if (mapping.type === "date") {
        return record[mapping.sourceField]
          ? toISODateString(record[mapping.sourceField])
          : "";
      }

      if (mapping.type === "choice" || mapping.type === "optionset" || mapping.type === "radio") {
        const value = record[mapping.sourceField];
        if (value === true) return "Yes";
        if (value === false) return "No";
        return value ?? "";
      }

      return record[mapping.sourceField] ?? "";
    }

    async function fetchConfiguredSourceRecord(copyConfig) {
      const source = copyConfig?.source;
      const parentGuid = getParentRecordGuid();

      if (!source?.entitySet) {
        throw new Error("copyFrom.source.entitySet is required in the section JSON.");
      }

      if (!parentGuid) {
        throw new Error("Parent record id was not found in the page URL.");
      }

      const filters = [];

      if (source.parentLookupField) {
        filters.push(`_${source.parentLookupField}_value eq ${parentGuid}`);
      }

      if (source.filter) {
        filters.push(`(${source.filter})`);
      }

      const filterQuery = filters.length
        ? `?$filter=${filters.join(" and ")}`
        : "";

      const url = `/_api/${source.entitySet}${filterQuery}`;

      console.log("[Schema-driven source copy] GET", url);

      const response = await safeWebApiClient({
        type: "GET",
        url: url,
        headers: {
          "Prefer": 'odata.include-annotations="OData.Community.Display.V1.FormattedValue"'
        }
      });

      const records = response?.value || [];
      return records.length ? records[0] : null;
    }

    async function populateConfiguredSource(section) {
      const formInstance = window.cmdsppForms[section.containerId];
      if (!formInstance) return false;

      // No hard-coded service-location/mailing-address field names.
      // The JSON decides which Yes/No field activates which source.
      const selectorField = (section.fields || []).find(field => {
        if (!field.copyFrom) return false;
        const currentValue = formInstance.formValues[field.name];
        return String(currentValue) === String(field.copyFrom.whenValue);
      });

      if (!selectorField) return false;

      const copyConfig = selectorField.copyFrom;
      const sourceRecord = await fetchConfiguredSourceRecord(copyConfig);

      if (!sourceRecord) {
        throw new Error(
          `No source record found for ${copyConfig.sourceType || "configured source"}.`
        );
      }

      const mappings = Array.isArray(copyConfig.mappings)
        ? copyConfig.mappings
        : [];

      if (!mappings.length) {
        throw new Error(
          `copyFrom.mappings is required for ${selectorField.name}.`
        );
      }

      mappings.forEach(mapping => {
        const targetField = mapping.targetField;
        if (!targetField) return;

        const value = getConfiguredSourceValue(sourceRecord, mapping);

        // Do not overwrite an existing billing value with empty source data.
        if (value === undefined || value === null || value === "") return;

        formInstance.formValues[targetField] = value;

        // Preserve lookup label so the UI and payload mapping can use it.
        if (mapping.type === "lookup" || mapping.type === "select") {
          const label = getSourceFormattedValue(
            sourceRecord,
            mapping.sourceField
          );

          if (label) {
            formInstance.formValues[`${targetField}_label`] = label;
            window.cmdsppOptionMaps = window.cmdsppOptionMaps || {};
            window.cmdsppOptionMaps[value] = label;
          }
        }
      });

      console.log(
        `[Schema-driven source copy] ${copyConfig.sourceType || "source"} -> ${section.sectionId}`,
        formInstance.formValues
      );

      return true;
    }

    // Flexible Payload Builder
    // ---------------------------------------------------------------------------
    // Payload builder
    // ---------------------------------------------------------------------------
    // The payload is still built from fieldMappings/fields, but the destination
    // table is NOT put into the payload. The destination table is selected by
    // submitSectionBatch() using the record's _entitySet. This is important when
    // one grid displays records coming from multiple Dataverse tables.
    function buildPayload(section, recordValues) {
      const payload = {};
      const mappings = section.fieldMappings || [];
      const fields = section.fields || [];

      if (mappings.length > 0) {
        mappings.forEach(mapping => {
          let value = recordValues[mapping.formField];
          if (value === undefined || value === null || value === "") return;

          if (mapping.type === "lookup") {
            const targetEntity =
              mapping.entitySet ||
              mapping.table ||
              mapping.source?.table ||
              "";

            if (!targetEntity) {
              console.warn(
                `No entitySet/table configured for lookup mapping ${mapping.formField}`
              );
              return;
            }

            payload[`${mapping.dataverseField}@odata.bind`] =
              `/${getEntitySet(targetEntity)}(${value})`;
          } else if (mapping.type === "optionset") {
            payload[mapping.dataverseField] =
              isNaN(value)
                ? (String(value).toLowerCase() === "yes" || value === true)
                : Number(value);
          } else if (mapping.type === "choice") {
            payload[mapping.dataverseField] =
              isNaN(value)
                ? String(value).toLowerCase() === "yes"
                  ? true
                  : false
                : Number(value);
          } else if (mapping.type === "date") {
            payload[mapping.dataverseField] = toISODateString(value);
          } else {
            payload[mapping.dataverseField] = value;
          }
        });
      } else {
        Object.keys(recordValues).forEach(fieldName => {
          // __ keys and _metadata keys are internal and must never be sent.
          if (
            fieldName.startsWith("__") ||
            fieldName.startsWith("_") ||
            fieldName.endsWith("_label")
          ) return;

          const value = recordValues[fieldName];
          if (value === undefined || value === null || value === "") return;

          const fieldDef = fields.find(f => f.name === fieldName);
          const fieldType = fieldDef ? fieldDef.type : null;

          if (fieldType === "lookup" || fieldType === "select") {
            const targetEntity =
              fieldDef?.source?.table ||
              fieldDef?.source?.entitySet ||
              fieldDef?.entitySet ||
              fieldName;

            payload[`${fieldName}@odata.bind`] =
              `/${getEntitySet(targetEntity)}(${value})`;
          } else if (fieldType === "optionset") {
            payload[fieldName] =
              isNaN(value)
                ? (String(value).toLowerCase() === "yes" || value === true)
                : Number(value);
          } else if (fieldType === "choice" || fieldType === "radio") {
            payload[fieldName] =
              isNaN(value)
                ? String(value).toLowerCase() === "yes"
                  ? true
                  : false
                : Number(value);
          } else if (fieldType === "date") {
            payload[fieldName] = toISODateString(value);
          } else if (fieldType === "checkbox") {
            payload[fieldName] =
              value === true || String(value).toLowerCase() === "true";
          } else {
            payload[fieldName] = value;
          }
        });
      }

      return payload;
    }

    // Updated Batch Submission
    //
    // valuesOverride is optional and is used by the Continue handler after
    // source-table values have been copied into the billing form. This keeps
    // the existing create/update/grid logic intact while guaranteeing that
    // the copied values are the values used to build the payload.
    async function submitSectionBatch(section, valuesOverride = null) {
      const parentAppGuid = getParentRecordGuid();
      const formInstance = window.cmdsppForms[section.containerId];
      const checkboxField = section.fields?.find(
        f => f.type === "checkboxgroup" || f.type === "multiselect"
      );

      const isStandalone =
        !section.tableId ||
        !Array.isArray(section.fieldMappings);

      // ---------------------------------------------------------------
      // Standalone checkbox / multi-select relation rows
      // ---------------------------------------------------------------
      if (checkboxField && isStandalone) {
        const checkedValues =
          (formInstance?.formValues[checkboxField.name] || []).map(String);
        const existingRows = section.records || [];
        const existingValues = existingRows.map(r =>
          String(r[`_${checkboxField.name}_value`] ?? r[checkboxField.name])
        );

        const toAdd = checkedValues.filter(v => !existingValues.includes(v));
        const toRemove = existingRows.filter(r =>
          !checkedValues.includes(
            String(r[`_${checkboxField.name}_value`] ?? r[checkboxField.name])
          )
        );

        const requests = [];

        for (const val of toAdd) {
          const entitySet =
            getEntitySetForRecord(section, {}) ||
            getSectionEntitySets(section)[0];
          const payload = {
            [`${checkboxField.name}@odata.bind`]:
              `/${getEntitySet(checkboxField.source.table)}(${val})`
          };

          const parentLookupField =
            getParentLookupFieldForEntity(section, entitySet, 0);

          if (parentAppGuid && parentLookupField) {
            payload[`${parentLookupField}@odata.bind`] =
              `/cmdspp_p_dtl_tbs(${parentAppGuid})`;
          }

          requests.push(
            safeWebApiClient({
              type: "POST",
              url: `/_api/${entitySet}`,
              data: JSON.stringify(payload)
            })
          );
        }

        for (const row of toRemove) {
          const entitySet = getEntitySetForRecord(section, row);
          const rowId =
            row.dbId ||
            row.recordId ||
            (row._recordIdField ? row[row._recordIdField] : null) ||
            getRecordIdFromEntityRecord(row, section, entitySet, row._entityIndex);

          if (!entitySet || !rowId) {
            console.warn("Unable to delete multi-table checkbox row", row);
            continue;
          }

          requests.push(
            safeWebApiClient({
              type: "PATCH",
              url: `/_api/${entitySet}(${rowId})`,
              data: JSON.stringify({ statecode: 1 })
            })
          );
        }

        await Promise.all(requests);
        section.records = await fetchSectionRecords(section);
        return;
      }

      // ---------------------------------------------------------------
      // Standalone / one-record section
      // ---------------------------------------------------------------
      if (isStandalone) {
        const formValues =
          valuesOverride ||
          (formInstance ? formInstance.formValues : {});

        if (formInstance && !formInstance.validateForm()) {
          formInstance.renderForm();
          throw new Error("Validation failed");
        }

        const payload = buildPayload(section, formValues);

        const entitySet =
          formValues.__entitySet ||
          getSectionEntitySets(section)[0];

        const parentLookupField =
          formValues.__parentLookupField ||
          getParentLookupFieldForEntity(section, entitySet, 0);

        if (parentAppGuid && parentLookupField) {
          payload[`${parentLookupField}@odata.bind`] =
            `/cmdspp_p_dtl_tbs(${parentAppGuid})`;
        }

        let existingRecordId =
          formValues.__recordId ||
          formValues.__editingId ||
          null;

        // If the form was not populated with an existing id, find the record
        // in the selected table by its parent lookup before deciding to POST.
        if (
          !existingRecordId &&
          parentAppGuid &&
          entitySet &&
          parentLookupField
        ) {
          const idField =
            formValues.__recordIdField ||
            getRecordIdFieldForEntity(section, entitySet, 0);

          if (idField) {
            const filter =
              `_${parentLookupField}_value eq ${parentAppGuid} and statecode eq 0`;
            const lookupUrl =
              `/_api/${entitySet}?$select=${idField}&$filter=${filter}`;

            try {
              const existingResponse = await safeWebApiClient({
                type: "GET",
                url: lookupUrl,
                headers: {
                  "Prefer":
                    'odata.include-annotations="OData.Community.Display.V1.FormattedValue"'
                }
              });

              const existingRecords = existingResponse?.value || [];
              if (existingRecords.length > 0) {
                existingRecordId = existingRecords[0][idField];
                formValues.__recordId = existingRecordId;
                formValues.__entitySet = entitySet;
                formValues.__recordIdField = idField;
              }
            } catch (lookupErr) {
              console.warn("Existing-record lookup failed; continuing with POST.", lookupErr);
            }
          }
        }

        console.log("[FINAL payload]", JSON.stringify(payload, null, 2));
        console.log("[operation]", existingRecordId ? "PATCH" : "POST");
        console.log("[entitySet]", entitySet);

        if (!entitySet) {
          throw new Error(`No entitySet configured for section ${section.sectionId}`);
        }

        if (existingRecordId) {
          return safeWebApiClient({
            type: "PATCH",
            url: `/_api/${entitySet}(${existingRecordId})`,
            data: JSON.stringify(payload)
          });
        }

        return safeWebApiClient({
          type: "POST",
          url: `/_api/${entitySet}`,
          data: JSON.stringify(payload)
        });
      }

      // ---------------------------------------------------------------
      // Sub-grid mode — each record carries its own destination table.
      // This is the important edit/delete fix for multi-table sections.
      // ---------------------------------------------------------------
      const toCreate = (section.records || [])
        .filter(r => r.isNew && !r.isDeleted);

      const toUpdate = (section.records || [])
        .filter(r => !r.isNew && !r.isDeleted && r.isEdited);

      const toDelete = (section.records || [])
        .filter(r => !r.isNew && r.isDeleted);

      const requests = [];

      for (const rec of toCreate) {
        const entitySet = getEntitySetForRecord(section, rec);
        if (!entitySet) {
          throw new Error("No destination entitySet found for new record.");
        }

        const payload = buildPayload(section, rec);
        const parentLookupField =
          rec._parentLookupField ||
          getParentLookupFieldForEntity(section, entitySet, rec._entityIndex);

        if (parentAppGuid) {
          const parentBindField =
            section.parentBindField ||
            (parentLookupField || "cmdspp_p_sys_id");
          payload[`${parentBindField}@odata.bind`] =
            `/cmdspp_p_dtl_tbs(${parentAppGuid})`;
        }

        requests.push(
          safeWebApiClient({
            type: "POST",
            url: `/_api/${entitySet}`,
            data: JSON.stringify(payload)
          })
        );
      }

      for (const rec of toUpdate) {
        const entitySet = getEntitySetForRecord(section, rec);
        const recordId = rec.dbId || rec.recordId;

        if (!entitySet || !recordId) {
          console.warn("Unable to update multi-table record", rec);
          continue;
        }

        const payload = buildPayload(section, rec);

        requests.push(
          safeWebApiClient({
            type: "PATCH",
            url: `/_api/${entitySet}(${recordId})`,
            data: JSON.stringify(payload)
          })
        );
      }

      for (const rec of toDelete) {
        const entitySet = getEntitySetForRecord(section, rec);
        const recordId = rec.dbId || rec.recordId;

        if (!entitySet || !recordId) {
          console.warn("Unable to delete multi-table record", rec);
          continue;
        }

        requests.push(
          safeWebApiClient({
            type: "PATCH",
            url: `/_api/${entitySet}(${recordId})`,
            data: JSON.stringify({ statecode: 1 })
          })
        );
      }

      return Promise.all(requests);
    }

    // Updated Section Loader
    async function loadSectionData(sec) {
      if (window.loadedSections.has(sec.sectionId)) return;

      const formInstance = new cmdsppFormRenderer(sec);
      await formInstance.renderMe();
      window.cmdsppForms[sec.containerId] = formInstance;

      const savedRecords = await fetchSectionRecords(sec);
      sec.records = savedRecords;
      // Render Sub-grid ONLY if tableId is present in schema
      if (sec.tableId) {
        const gridInstance = new CommonTableTemplate(sec.tableId, {
          actions: {
            onEdit: (rec) => formInstance.setValues(rec, rec.recordId || rec.dbId),
            onDelete: (rec) => {
              if (confirm("Are you sure you want to remove this record?")) {
                rec.isDeleted = true;
                gridInstance.render(sec.columns, sec.records, sec.fields);
              }
            }
          }
        });

        window.cmdsppGrids[sec.tableId] = gridInstance;

        gridInstance.render(sec.columns, sec.records, sec.fields);
      }

      window.loadedSections.add(sec.sectionId);
    }

    function bindAccordion() {
      $(document).off("click", ".accordion-container fieldset legend").on("click", ".accordion-container fieldset legend", async function () {
        const fieldset = $(this).closest("fieldset");
        const secContainer = $(this).closest(".accordion-container");
        const secId = secContainer.attr("id");
        const section = window.wizardSchema.find(s => s.sectionId === secId);

        // Lazy load section data if not loaded yet
        if (section && !window.loadedSections.has(secId)) {
          await loadSectionData(section);
        }

        fieldset.find(".accordion-content").slideToggle(200);
        fieldset.toggleClass("active");
      });
    }

    async function initializePage() {
      const container = document.getElementById("wizardContainer");
      // container.innerHTML = `<div id="cmdspp-page-loader" class="cmdspp-loader-overlay">
      //   <div class="cmdspp-loader-content">
      //     <div class="spinner-border text-primary" role="status" style="width: 3rem; height: 3rem;">
      //       <span class="visually-hidden">Loading...</span>
      //     </div>
      //     <div class="mt-3 fw-bold text-secondary">Loading Application Form...</div>
      //   </div>
      // </div>`;
      const startTime = performance.now();
      const startDate = new Date();
      console.log(`%c[Initialization Started] %c${startDate.toLocaleTimeString()}.${startDate.getMilliseconds()}`, "color: #0d6efd; font-weight: bold;", "color: #333;");

      const loaderEl = document.getElementById("cmdspp-page-loader");

      container.innerHTML = window.wizardSchema.map((sec, index) => {

        const hasTable = !!sec.tableId && Array.isArray(sec.fieldMappings);
        return `<div class="accordion-container" id="${sec.sectionId}">
        <fieldset class="${index === 0 ? 'active' : ''}">
          <legend>
            <div class="accordion-header">
              <div class="accordion-title">
                <span class="step-circle">${sec.headerPrefix}</span>
                <span>${sec.header}</span>
              </div>
              <span class="accordion-arrow ${index === 0 ? 'active' : ''}"></span>
            </div>
          </legend>
          <div class="accordion-content" style="display:${index === 0 ? 'block' : 'none'};">
           ${sec.instructions ? `
         <div class="cmdspp-instruction-box mb-4">
           ${sec.instructions.title ? `
           <div class="cmdspp-instruction-title">
             ${sec.instructions.title}
           </div>
           ` : ""}
           ${(sec.instructions.paragraphs || [])
           .map(p => `<p class="mb-2">${p}</p>`)
           .join("")}
           ${sec.instructions.subTitle ? `
           <div class="cmdspp-instruction-title mt-3">
             ${sec.instructions.subTitle}
           </div>
           ` : ""}
           ${(sec.instructions.subParagraphs || [])
           .map(p => `<p class="mb-2">${p}</p>`)
           .join("")}
         </div>
         ` : ""}
            <div class="p-3 mb-4 border rounded bg-light">
              <div id="${sec.containerId}"></div>
            </div>
            ${hasTable ? `
            <div class="mb-2">
              <div id="${sec.tableId}">
                <div class="cmdspp-table-wrapper">
                  <table class="cmdspp-common-table cmdspp-header-table"><thead id="cmdspp-table-header"></thead></table>
                  <div class="cmdspp-table-container">
                    <table class="cmdspp-common-table cmdspp-body-table"><tbody id="cmdspp-table-body"></tbody></table>
                  </div>
                  <div class="cmdspp-table-pagination">
                    <div class="cmdspp-pagination-info" id="cmdspp-pagination-info">Showing 0 entries</div>
                    <div class="cmdspp-pagination-controls">
                      <button id="cmdspp-prev-page" class="cmdspp-page-btn" disabled>&larr;</button>
                      <div id="cmdspp-page-numbers" class="cmdspp-page-numbers">
                        <button type="button" class="cmdspp-page-number active" data-page="1" disabled>1</button>
                      </div>
                      <button id="cmdspp-next-page" class="cmdspp-page-btn" disabled>&rarr;</button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ` : ''}
            <div class="d-flex justify-content-between align-items-center pt-3 border-top">
              <button type="button" id="${sec.resetBtnId}" class="btn-reset-custom">Reset</button>
                <div class="d-flex gap-2">
            ${sec.noBackButton !== true ? `
    <button
        type="button"
        id="${sec.submitBtnId}_back"
        class="btn-back-custom"
        data-current="${sec.sectionId}"
        data-previous="${sec.prevSectionId}">
        Back
    </button>
` : ''}
             <button type="button" id="${sec.submitBtnId}" class="btn-continue-custom" data-current="${sec.sectionId}">Continue</button>
             </div>
           </div>
          </div>
        </fieldset>
      </div>`}).join("");

      window.cmdsppForms = window.cmdsppForms || {};
      window.cmdsppGrids = window.cmdsppGrids || {};

      bindAccordion();

      // 1. Immediately load Section 1 for instant initial page render
      if (window.wizardSchema.length > 0) {
        await loadSectionData(window.wizardSchema[0]);
      }

      const endTime = performance.now();
      const totalDurationSec = ((endTime - startTime) / 1000).toFixed(2);
      console.log(`%c[Section 1 Initialized] %c${totalDurationSec}s)`, "color: #198754; font-weight: bold;", "color: #333;");

      // 2. Pre-fetch remaining sections in background WITHOUT blocking initialization!
      if (window.wizardSchema.length > 1) {
        const remainingSections = window.wizardSchema.slice(1);

        Promise.allSettled(remainingSections.map(sec => loadSectionData(sec))).then(() => {
          const endTime_rest = performance.now();
          const totalDurationSec_rest = ((endTime_rest - startTime) / 1000).toFixed(2);
          console.log(`%c[All Sections Loaded] ${totalDurationSec_rest}s)`, "color: #0dcaf0; font-weight: bold;");
        });
      }

      window.addEventListener("dynamicFormSubmit", (e) => {
        const detail = e.detail;
        const section = window.wizardSchema.find(s => s.containerId === detail.containerId);
        if (!section) return;

        if (detail.isEditing) {
          const existing = section.records.find(r => String(r.recordId || r.dbId) === String(detail.editingId));
          if (existing) {
            Object.assign(existing, detail.values);
            existing.isEdited = true;
          }
        } else {
          const newId = "new-" + Date.now();
          section.records.push(Object.assign({ recordId: newId, dbId: newId, isNew: true }, detail.values));
        }

        const grid = window.cmdsppGrids[section.tableId];
        if (grid) {
          grid.render(section.columns, section.records, section.fields);
        }
      });


      $(document).off("click", ".btn-reset-custom").on("click", ".btn-reset-custom", async function (e) {
        e.preventDefault();
        const sectionId = $(this).closest(".accordion-container").attr("id");
        console.log(sectionId);
        const section = window.wizardSchema.find(s => s.sectionId === sectionId);
        if (section && window.cmdsppForms[section.containerId]) {
          window.cmdsppForms[section.containerId].reset();
        }
      })

      $(document).off("click", ".btn-back-custom").on("click", ".btn-back-custom", async function (e) {
        e.preventDefault();
        const secId = this.getAttribute("data-current");
        const section = window.wizardSchema.find(s => s.sectionId === secId);
        if (!section) return;


        try {
          if (section.prevSectionId) {
            const prevSec = window.wizardSchema.find(s => s.sectionId === section.prevSectionId);
            if (prevSec) {
              await loadSectionData(prevSec);
            }
            // Close all accordions
            $(".accordion-container fieldset").removeClass("active");
            $(".accordion-container .accordion-content").slideUp();
            $(".accordion-container .accordion-arrow").removeClass("active");
            $(`#${section.prevSectionId} fieldset`).addClass("active").find(".accordion-content").slideDown();
          }
        } catch (err) {
          console.error("Save failed:", err);
        }
        finally {

        }
      });

      function onOpenAccordion(nextSectionId) {
        $(".accordion-container fieldset").removeClass("active");
        $(".accordion-container .accordion-content").slideUp();
        $(".accordion-container .accordion-arrow").removeClass("active");
        $(`#${nextSectionId} fieldset`).addClass("active").find(".accordion-content").slideDown();
      }

      $(document).off("click", ".btn-continue-custom").on("click", ".btn-continue-custom", async function (e) {
        e.preventDefault();
        const secId = this.getAttribute("data-current");
        const section = window.wizardSchema.find(s => s.sectionId === secId);
        if (!section) return;

        this.disabled = true;
        this.textContent = "Saving...";

        try {
          // If this section contains a JSON copyFrom configuration and the
          // configured Yes/No value is selected, fetch the source record
          // first. The source/target column names are resolved entirely from
          // JSON mappings.
          await populateConfiguredSource(section);

          // Snapshot AFTER source population. This prevents any later UI
          // rendering from changing what is sent to Dataverse.
          const formInstance = window.cmdsppForms[section.containerId];
          const valuesForSave = formInstance
            ? { ...formInstance.formValues }
            : {};
           const isStandalone = !section.tableId || !section.fieldMappings;
          if (formInstance && !formInstance.validateForm() && isStandalone) {
            formInstance.renderForm();
            throw new Error("Validation failed");
          }

          await submitSectionBatch(section, valuesForSave);
          this.disabled = false;
          this.textContent = "Continue";
          if (section.nextSectionId) {
            const nextSec = window.wizardSchema.find(s => s.sectionId === section.nextSectionId);
            if (nextSec && !window.loadedSections.has(nextSec.sectionId)) {
              await loadSectionData(nextSec);
            }
            onOpenAccordion(section.nextSectionId)
          } else {
           if (section.isDynamicNav) {
              const formInstance = window.cmdsppForms[section.containerId];
              const checkboxField = section.fields?.find(f => f.type === "checkboxgroup" || f.type === "multiselect");
          
              section.dependency?.forEach(dep => {
                if (dep.type !== "navigation") return;
          
                let found = false;
          
                if (checkboxField && dep.depId.includes(checkboxField.name)) {
                  // Multi-select: check ALL currently selected values by label
                  const selectedValues = formInstance?.formValues[checkboxField.name] || [];
                  found = selectedValues.some(v => String(getLabelFromLookupCache(v)) === String(dep.value));
          
                  if (found) {
                    window.location.href = `${dep.urltoNavigate}${window.location.search}`;
                  } else {
                    // Last section for this checkbox flow — go straight to the section's nextPageUrl
                    window.location.href = `${section.nextPageUrl}${window.location.search}`;
                  }
                } else {
                  // Original single-record behavior (e.g. section-o's EFT radio) — unchanged
                  found = dep.depId.some(key => section.records?.[0]?.[key] === dep.value);
                  if (found) {
                    window.location.href = `${dep.urltoNavigate}${window.location.search}`;
                  } else {
                    onOpenAccordion(dep.nextSectionId);
                  }
                }
              });
            }
            else window.location.href = `${section.nextPageUrl}${window.location.search}`
          }
        } catch (err) {
          this.disabled = false;
          this.textContent = "Continue";
          console.error("Save failed:", err);
        }
        finally {
          // 4. Guaranteed Execution: Hide Loader Overlay & Print Timings
          // if (loaderEl) {
          //   loaderEl.classList.add("hidden");
          // }

          const endTime = performance.now();
          const endDate = new Date();
          const totalDurationSec = ((endTime - startTime) / 1000).toFixed(2);

          console.log(`%c[Finally Block Initialization Completed] %c${endDate.toLocaleTimeString()}.${endDate.getMilliseconds()}`, "color: #198754; font-weight: bold;", "color: #333;");
          console.log(`%c[Finally Block Total Load Time] %c${totalDurationSec}s (${(endTime - startTime).toFixed(0)} ms)`, "color: #0dcaf0; font-weight: bold;", "color: #333;");
        }
      });
    }

    $(document).ready(function () {
      // Defer execution slightly if webapi is still loading
      if (typeof window.webapi === "undefined") {
        console.warn("webapi object not ready yet, falling back to standard AJAX.");
      }

      initializePage();
    });
  })();
</script>

<script>
(function () {
  "use strict";

  function hideCmdsppLoader() {
    const loader = document.getElementById("cmdspp-page-loader");
    if (loader) loader.classList.add("hidden");
  }

  function waitForWizardLoad() {
    const loader = document.getElementById("cmdspp-page-loader");
    if (!loader) return;

    if (
      window.wizardSchema &&
      window.wizardSchema.length > 0 &&
      window.loadedSections &&
      window.loadedSections.has(window.wizardSchema[0].sectionId)
    ) {
      hideCmdsppLoader();
      return;
    }

    if (window.wizardSchema && window.wizardSchema.length === 0) {
      hideCmdsppLoader();
      return;
    }

    setTimeout(waitForWizardLoad, 50);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", waitForWizardLoad);
  } else {
    waitForWizardLoad();
  }
})();
</script>"
}
